'use strict';
let glossaryQuery='',glossaryCategory='all',dayRole='dev';
const normalized=s=>s.toLocaleLowerCase('hu-HU').normalize('NFD').replace(/\p{Diacritic}/gu,'');
function renderLearn(){
 $('#learn-view').innerHTML=`<div class="page-intro"><div class="eyebrow">TUDÁSTÁR / TECH NYELVEN, EMBERIÜL</div><h1>A nagy szavak mögött<br><span>egyszerű ötletek vannak.</span></h1><p>Nem szótárat kell bemagolnod. Kapcsolj egy új fogalmat valamihez, amit már ismersz!</p></div><div class="glossary-toolbar"><label class="search-field">${icon('book')}<span class="sr-only">Fogalom vagy példa keresése</span><input id="glossary-search" type="search" placeholder="Keress rá: pl. bug, robot, feltétel…" value="${escapeHTML(glossaryQuery)}" autocomplete="off"></label><div class="filter-buttons" role="group" aria-label="Fogalmak szűrése">${[['all','Minden'],['alapok','Alapok'],['fejlesztés','Fejlesztés'],['tesztelés','Tesztelés']].map(([v,t])=>`<button data-action="glossary-category" data-category="${v}" class="${v===glossaryCategory?'selected':''}" aria-pressed="${v===glossaryCategory}">${t}</button>`).join('')}</div></div><p class="glossary-count" id="glossary-count" role="status" aria-live="polite"></p><div class="glossary-grid" id="glossary-grid"></div><div class="learning-panel"><h2>A legjobb következő lépés? Próbáld ki.</h2><p>A fogalmak a játékban életre kelnek: az algoritmus a robot útja, a feltétel a miniapp döntése, a teszteset pedig egy konkrét próba.</p><div class="game-actions" style="margin-top:20px"><button class="button primary" data-action="mission" data-mission="0">${icon('code')}Robotprogramozás</button><button class="button secondary" data-action="bonus" data-bonus="quiz">Tech radar${icon('arrow')}</button></div></div>`;
 $('#glossary-search').addEventListener('input',e=>{glossaryQuery=e.target.value;renderGlossaryResults();});renderGlossaryResults();
}
function renderGlossaryResults(){const words=GLOSSARY.filter(a=>(glossaryCategory==='all'||a[1]===glossaryCategory)&&normalized(a.join(' ')).includes(normalized(glossaryQuery.trim())));$('#glossary-count').textContent=`${words.length} / ${GLOSSARY.length} fogalom`;$('#glossary-grid').innerHTML=words.length?words.map(([term,category,meaning,example])=>`<article class="glossary-card"><span class="glossary-category">${category}</span><h2>${term}</h2><p>${meaning}</p><div class="glossary-example"><span>PÉLDÁUL</span>${example}</div></article>`).join(''):`<div class="empty-search"><h2>Erre még nincs találat.</h2><p>Próbálj rövidebb kifejezést, vagy válts a „Minden” kategóriára.</p><button class="button secondary" data-action="glossary-clear">Keresés törlése${icon('reset')}</button></div>`;}
function renderBadges(){const badges=DIFFICULTIES.flatMap(d=>[['code','Logikus gondolkodó'],['bug','Hibavadász'],['rocket','Ötletgazda']].map(([ic,name],i)=>({icon:ic,name,tier:d.name,earned:game.profiles[d.id].completed.includes(i),desc:['Három robotpálya megoldása.','Három teszthelyzet megvizsgálása.','Egy saját miniapp elkészítése.'][i],mission:i,difficulty:d.id})));badges.push({icon:'code',name:'Kódnyomozó',tier:'Bónusz',earned:game.bonus.debug.length===3,desc:'Három logikai hiba kijavítása.',bonus:'debug'},{icon:'spark',name:'Tech radar',tier:'Bónusz',earned:game.bonus.quiz.filter(Boolean).length===6,desc:'Hat kérdés és magyarázat felfedezése.',bonus:'quiz'});const earned=badges.filter(b=>b.earned).length;
 $('#badges-view').innerHTML=`<div class="page-intro"><div class="eyebrow">A SAJÁT TECH-UTAD</div><h1>Kis felismerések.<br><span>Nagy gyűjtemény.</span></h1><p>Minden jelvény egy kipróbált gondolkodásmód. Nincs ranglista: a tegnapi önmagadhoz képest haladsz.</p></div><div class="collection-overview"><div><strong>${earned}<span> / ${badges.length}</span></strong><span>megszerzett jelvény</span></div><div><strong>${totalXP()}<span> XP</span></strong><span>összegyűjtött tapasztalat</span></div><div><strong>${DIFFICULTIES.filter(d=>game.profiles[d.id].completed.length===3).length}<span> / 3</span></strong><span>teljesített nehézségi szint</span></div></div><div class="badge-grid">${badges.map(b=>`<article class="badge-card ${b.earned?'earned':'not-earned'}"><span class="badge-emblem">${icon(b.icon)}${b.earned?'<i>✓</i>':''}</span><span class="badge-tier">${b.tier}</span><h2>${b.name}</h2><p>${b.desc}</p>${b.earned?'<span class="badge-status">'+icon('check')+'Megszerezve</span>':`<button class="text-button" data-action="${b.bonus?'bonus':'badge-mission'}" ${b.bonus?`data-bonus="${b.bonus}"`:`data-mission="${b.mission}" data-difficulty="${b.difficulty}"`}>Kipróbálom${icon('arrow')}</button>`}</article>`).join('')}</div><div class="result-actions"><button class="button secondary" data-action="export-progress">${icon('down')}Kalandom mentése</button><button class="text-button" data-action="reset">Új felfedező${icon('reset')}</button></div><p class="collection-note">Az XP és a jelvények a játékban kipróbált feladatokat jelzik. Nem osztályzatok és nem pályaalkalmassági eredmények.</p>`;
}
const WORKDAYS={
 dev:[['09:00','Egyeztetés','A csapat megbeszéli, min dolgozik. Te jelzed, hogy a jegyvásárló oldal űrlapját készíted.'],['10:00','Tervezés és kódolás','Kisebb feladatokra bontod a munkát: beviteli mezők, kedvezményszámítás, visszajelzés.'],['13:00','Kipróbálás','Ellenőrzöd a kódodat. A tesztelő jelzi, hogy a 14 évesek kedvezménye nem működik.'],['15:00','Javítás és közös átnézés','Megkeresed az eltérő feltételt. Egy másik fejlesztő átnézi a változtatást, majd újra teszteltek.']],
 test:[['09:00','A feladat megértése','Elolvasod, hogyan kellene működnie a jegyvásárlásnak. Kérdezel, ha a korhatár nem egyértelmű.'],['10:00','Tesztesetek tervezése','Összegyűjtöd a próbákat: üres név, helyes kupon, 13/14/15 éves kor. Leírod a várt eredményeket.'],['13:00','Próbák és hibajelentés','Megismételhető lépésekben leírod: 14 éves kor + kupon → nincs kedvezmény, pedig járna.'],['15:00','Újratesztelés','A javítás után ellenőrzöd az eredeti hibát és a közeli eseteket is, nehogy valami más romoljon el.']]
};
function renderProfessionExtras(){let box=$('#profession-extras');if(!box){box=document.createElement('div');box.id='profession-extras';$('#profession-view').append(box);}box.innerHTML=`<section class="day-section"><div class="section-heading"><div><div class="eyebrow small">ILLUSZTRATÍV MUNKANAP</div><h2>Egy app. Két nézőpont.</h2></div><div class="filter-buttons" role="group" aria-label="Munkanap szerepköre"><button data-action="day-role" data-role="dev" class="${dayRole==='dev'?'selected':''}" aria-pressed="${dayRole==='dev'}">${icon('code')}Fejlesztőként</button><button data-action="day-role" data-role="test" class="${dayRole==='test'?'selected':''}" aria-pressed="${dayRole==='test'}">${icon('bug')}Tesztelőként</button></div></div><div class="day-timeline" id="day-timeline"></div><p class="section-note">Szemléltető példa, nem egy konkrét munkahely napirendje. A feladatok és szerepek csapatonként változnak.</p></section><section class="learning-roadmap"><div class="eyebrow small">AMIT LÉPÉSRŐL LÉPÉSRE FELÉPÍTHETSZ</div><h2>Nem készen kell érkezned.</h2><div class="roadmap-grid">${[['01','Alapok','Logika, egyszerű algoritmusok, adatok és első programok.'],['02','Alkalmazások','Webes felületek, háttérlogika és adatbázisok összekapcsolása.'],['03','Minőség','Tesztesetek, hibajelentések és később automatizált ellenőrzések.'],['04','Közös projektek','Feladatmegosztás, verziókezelés, bemutatás és visszajelzés.']].map(([n,t,p])=>`<article><span>${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="project-examples"><div class="section-heading"><div><div class="eyebrow small">ILYEN ÖTLETEKBŐL LEHET PROJEKT</div><h2>Olyasmit építhetsz, amit használnál is.</h2></div></div><div class="project-grid"><article>${icon('clock')}<h3>Tanulástervező</h3><p>Feladatlista és határidők. Fejlesztőként megvalósítod a mentést; tesztelőként ellenőrzöd a lejárt és üres dátumokat.</p></article><article>${icon('people')}<h3>Iskolai eseményapp</h3><p>Jelentkezés egy programra. Megtervezed az űrlapot, majd kipróbálod, mi történik az utolsó szabad helynél.</p></article><article>${icon('rocket')}<h3>Saját böngészős játék</h3><p>Pontszám, pályák, újrakezdés. A tesztjeid megmutatják, tényleg helyesen számolja-e a találatokat.</p></article></div></section><section class="career-faq"><div class="eyebrow small">AMIT SOKAN MEGKÉRDEZNEK</div><h2>Beszéljünk róla őszintén.</h2>${[
 ['Kell már tudnom programozni a jelentkezéshez?','Ez a bemutató előismeret nélkül készült. A konkrét felvételi feltételeket az adott technikum tájékoztatójában ellenőrizd. A kíváncsiságot, a rendszeres gyakorlást és a segítségkérést már most érdemes magaddal hoznod.'],
 ['Csak annak való, aki zseni matekból?','A logikus gondolkodás és a matematikai alapok hasznosak, de a fejlesztés sok tanulható készségből áll: feladatbontás, pontos megfogalmazás, gyakorlás és együttműködés. Egy rövid játék nem dönti el, kinek való a szakma.'],
 ['A tesztelő csak nyomkodja a gombokat?','A kipróbálás mögött terv van. A tesztelő megérti a követelményeket, megtervezi az eseteket, értékeli az eredményt és jól megfogalmazott visszajelzést ad. Később kóddal automatizálhatja az ismétlődő ellenőrzéseket.'],
 ['Miért tanuljak programozást, ha van AI?','Az AI segíthet ötletelni és kódot írni, de a cél megértése, a döntések és az ellenőrzés továbbra is számítanak. Az alapokkal felismered a hibás javaslatokat, és tudatosabban használod az eszközt.'],
 ['Milyen irányokba indulhatok tovább?','A megszerzett alapokra épülhet például webfejlesztés, alkalmazásfejlesztés, tesztautomatizálás vagy további informatikai tanulmány. A konkrét lehetőségekhez a képzés tartalmát, a további követelményeket és a saját érdeklődésedet is nézd meg.'],
 ['Mit kérdezzek a nyílt napon?','Kérj diákprojekt-bemutatót! Kérdezd meg: „Hogyan segítetek, ha elakadok?”, „Milyen eszközökkel dolgozunk?”, „Mennyi a közös projekt?”, „Hogyan gyakoroljuk a tesztelést?”, „Mi a pontos felvételi feltétel?”']
 ].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</section><div class="learning-panel"><h2>A kíváncsiságodat már most továbbviheted.</h2><p>Keress egy valódi iskolai projektet a bemutatókon, és kérdezd meg a készítőit, hogyan kezdték. A tanterv, az óraszám és a felvételi intézményenként eltérhet.</p><div class="game-actions" style="margin-top:20px"><button class="button primary" data-action="start">Kipróbálom magam${icon('arrow')}</button><button class="button secondary" data-action="learn">${icon('book')}Fogalmak érthetően</button></div></div>`;renderDay();}
function renderDay(){$('#day-timeline').innerHTML=WORKDAYS[dayRole].map(([time,title,desc])=>`<article><time>${time}</time><span class="timeline-dot"></span><div><h3>${title}</h3><p>${desc}</p></div></article>`).join('');}
actions['glossary-category']=b=>{glossaryCategory=b.dataset.category;$$('.filter-buttons [data-category]').forEach(x=>{x.classList.toggle('selected',x.dataset.category===glossaryCategory);x.setAttribute('aria-pressed',String(x.dataset.category===glossaryCategory));});renderGlossaryResults();};
actions['glossary-clear']=()=>{glossaryCategory='all';glossaryQuery='';renderLearn();$('#glossary-search').focus();};
actions['day-role']=b=>{dayRole=b.dataset.role;$$('[data-action="day-role"]').forEach(x=>{x.classList.toggle('selected',x.dataset.role===dayRole);x.setAttribute('aria-pressed',String(x.dataset.role===dayRole));});renderDay();};
actions['badge-mission']=b=>{chooseDifficulty(b.dataset.difficulty);openMission(Number(b.dataset.mission));};
actions['export-progress']=()=>{const text='KÓDRA FEL! – A TECH-KALANDOM\n\n'+DIFFICULTIES.map(d=>`${d.name}: ${game.profiles[d.id].completed.length}/3 küldetés\n  Robotpályák: ${game.profiles[d.id].robotSolved.length}/3\n  Teszthelyzetek: ${game.profiles[d.id].testReports.length}/3`).join('\n\n')+`\n\nKódnyomozó: ${game.bonus.debug.length}/3\nTech radar: ${game.bonus.quiz.filter(Boolean).length}/6\nÖsszesen: ${totalXP()} XP\n\nEz egy játékos felfedezés összegzése, nem osztályzat vagy pályaalkalmassági eredmény.\nKövetkező kérdésem a nyílt napon: Milyen saját projekteket készíthetek nálatok?\n`;downloadBlob(text,'tech-kalandom.txt','text/plain;charset=utf-8');};
